/** App-derived report state (CT-4 reportStateOf) → label. */
export const ctReportStateLabel = (v?: string | null): string => {
  const bn: Record<string, string> = { not_started: "শুরু হয়নি", in_progress: "চলমান", complete: "সম্পূর্ণ", overdue: "বিলম্বিত" };
  const en: Record<string, string> = { not_started: "Not started", in_progress: "In progress", complete: "Complete", overdue: "Overdue" };
  return (v && pick(bn, en)[v]) || v || DASH;
};
/** App-derived trend (CT-4 trendOf) → arrow glyph. */
export const ctTrendGlyph = (v?: string | null): string =>
  v === "up" ? "↑" : v === "down" ? "↓" : v === "flat" ? "→" : DASH;

